/// <summary>
/// PricingAttribute of table <c>InventTable</c> field Density.
/// </summary>
[UPSPricingMetadataDiscovery][UPSPricingAttributeSourceDiscovery(UPSPricingAttributeSource::Product, UPSPricingAttributeSourceLevel::Line)]
internal class UPSPricingAttributeInventTableDensity extends UPSPricingAttributeInventTable implements UPSIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(InventTable, Density);
}

public Set getAllowedValues()
{
    var ret = new Set(Types::Real);
    InventTable inventTable;
    while select Density from inventTable
        group by Density
    {
        ret.add(inventTable.Density);
    }
    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    qbr = _qbds.addRange(fieldNum(InventTable, Density));
    qbr.value(queryValue(_value));
}
